\u0057\u0060\u0066\u007d\u0052\u003a\u0043\u006a\u0058\u0038\u0058\u004b\u0037\u0059\u0074\u006b\u004f\u0075\u0055\u007c\u007d\u0034\u0073\u004f\u0036\u0047\u0041\u007d\u0072\u0077\u0022\u0022\u0037\u003c\u004b\u0044\u004f\u0024\u0031\u0079\u004d\u0054\u004e\u006d\u003c\u0054\u005e\u0029\u002a\u0027\u002e\u0079\u0062\u0072\u0078\u005e\u002e\u006f\u0041\u0047\u005a\u0050\u007b\u0042\u006b\u0058\u0031\u0078\u005f\u0022\u002f\u0035\u0031\u0050\u0064\u006a\u002e\u0076\u0041\u005b\u0032\u006d\u006d\u0047\u002b\u0028\u003b\u003c\u004e\u0044\u0074\u0044\u0075\u0040\u0066\u0065\u006a\u0049\u0039\u0061\u002c\u002d\u0026\u003e\u007c\u004c\u0034\u0054\u004c\u0062\u0028\u007d\u007c\u003c\u0059\u0037\u0077\u0058\u0045\u0025\u0030\u005c\u0028\u0051\u002e\u0044\u0031\u0042\u002f\u003d\u002f\u0038\u0076\u003d\u0031\u004e\u0035\u0035\u006f\u0053\u0022\u002a\u0064\u0039\u0029\u0056\u0078\u0049\u0057\u0029\u0077\u0070\u005e\u0044\u0043\u0020\u0030\u0035\u003e\u002d\u007d\u0078\u002d\u0056\u005e\u0022\u005b\u0044\u003e\u004f\u0068\u0075\u0032\u0021\u0027\u0029\u004d\u0030\u0070\u0074\u006b\u006d\u005c\u006e\u0061\u0054\u0031\u0032\u005d\u007d\u0070\u0073\u0038\u003a\u0079\u0059\u002f\u003d\u0022\u0071\u003b\u007c\u0055\u0076\u0037\u0024\u005a\u0070\u0049\u0053\u0064\u002d\u0038\u0028\u0034\u0026\u0071\u0048\u0068\u0053\u0056\u006c\u0063\u0079\u004b\u002b\u006d\u0044\u0052\u006e\u0079\u002e\u0064\u0046\u0074\u0020\u0027\u0033\u0039\u0047\u006e\u004e\u003d\u005f\u0032\u0048\u007d\u0038\u004f\u0030\u004b\u0046\u0076\u004d\u0036\u0042\u0053\u006a\u006e\u0079\u0067\u0078\u007d\u0026\u0044\u0038\u0064\u0035\u0057\u0079\u003e\u005a\u005c\u0040\u006a\u0053\u003c\u005a\u0029\u0074\u003b\u003e\u0048\u006c\u0069\u004a\u007b\u0079\u0024\u0049\u0071\u0047\u002c\u004e\u006a\u0034\u004c\u0039\u0033\u002f\u005a\u0057\u0071\u003e\u002a\u0030\u0047\u0031\u0032\u005e\u002a\u0043\u007a\u0030\u0029\u0039\u0069\u003c\u0061\u0073\u002c\u0042\u0055\u0075\u002c\u0038\u0064\u003b\u006b\u0058\u0031\u003e\u004f\u0072\u0034\u0036\u0079\u0020\u005d\u0072\u0032\u0021\u0051\u003d\u0050\u0024\u006d\u0076\u004c\u002d\u004f\u005a\u005e\u0057\u0045\u003f\u0040\u0063\u003d\u0047\u0064\u002e\u0027\u007c\u004b\u0036\u005b\u004e\u0073\u0060\u003b\u003f\u0046\u0069\u0079\u0061\u007e\u006f\u0023\u0044\u0063\u0059\u0040\u0028\u0022\u0060\u0028\u0047\u0064\u007e\u006c\u0065\u0069\u004a\u005a\u002e\u0020\u0026\u006d\u0073\u0064\u0029\u0034\u0067\u0074\u003c\u002e\u0054\u0025\u003e\u002e\u0033\u0058\u0049\u0025\u0061\u0078\u002f\u0066\u0060\u006b\u005a\u0049\u005e\u0046\u0061\u002c\u0031\u002c\u003c\u005f\u006d\u0079\u0026\u0061\u003f\u0042\u0063\u0074\u003e\u003d\u0043\u0034\u0063\u0051\u003f\u003b\u0036\u0036\u002d\u006e\u0065\u0068\u0075\u0067\u007d\u005e\u0029\u0031\u0038\u0040\u003d\u0039\u007d\u004b\u0039\u0054\u006c\u0069\u0031\u0033\u0023\u0067\u003b\u0058\u0073\u0078\u0074\u002d\u0032\u0062\u0073\u0022\u007a\u0060\u0071\u006d\u0032\u0046\u004b\u0061\u0041\u003e\u004f\u003b\u002c\u0040\u0034\u0030\u005b\u0034\u003d\u004b\u0028\u0020\u0075\u004a\u0075\u0057\u003e\u005c\u0063\u006e\u005d\u0024\u005b\u005d\u0075\u003d\u003c\u0060\u0022\u0059\u0035\u0073\u005f\u0033\u0026\u0064\u0050\u006a\u005d\u0056\u002e\u0029\u0075\u002f\u004f\u004e\u004c\u004a\u0054\u0022\u0076\u0061\u002e\u005c\u0051\u0048\u0071\u0023\u0040\u002b\u0064\u0044\u0040\u0071\u002a\u0038\u0063\u0072\u0069\u002b\u0060\u006f\u002a\u002f\u0039\u0071\u002e\u004c\u0071\u0045\u0023\u0032\u0079\u003e\u0071\u006b\u006e\u005b\u003d\u002e\u005c\u0075\u0029\u004a\u0034\u0031\u0036\u004f\u0039\u0070\u002a\u0021\u006f\u005b\u0029\u0077\u007b\u006c\u0055\u0058\u0040\u0033\u006f\u0039\u002f\u0021\u0063\u003c\u007e\u0056\u0072\u006c\u0037\u0039\u0030\u0024\u0039\u0048\u003f\u006f\u002b\u005b\u006e\u0056\u0042\u0027\u0045\u005c\u0057\u0044\u0059\u005d\u0064\u0059\u0047\u003a\u007c\u0075\u006c\u0024\u007b\u0033\u007c\u0038\u004c\u0032\u0038\u0046\u0069\u0027\u0076\u0041\u0047\u0022\u0042\u0033\u0076\u007e\u0034\u005f\u0045\u004c\u0047\u003d\u0022\u004b\u002f\u004e\u0034\u0076\u0042\u0042\u0057\u0021\u003f\u0078\u0073\u0061\u0069\u0033\u005a\u0028\u0072\u0061\u002d\u0029\u006a\u003a\u0059\u005f\u0036\u007d\u0064\u0078\u004a\u005f\u0074\u005b\u0031\u0073\u002a\u0075\u0072\u003d\u0021\u0035\u004c\u0056\u006f\u0041\u0050\u0047\u0040\u0045\u0067\u006f\u002b\u002b\u005d\u004b\u0022\u0041\u0027\u0052\u0045\u0055\u0051\u0039\u0072\u0044\u002e\u0042\u002c\u005f\u002c\u0070\u0021\u004a\u005c\u0022\u0027\u006d\u006f\u006c\u0045\u0038\u0058\u003f\u0066\u0067\u003b\u0052\u0022\u0059\u003c\u0041\u0079\u002c\u003d\u0058\u005e\u004b\u003a\u0056\u0036\u0069\u0022\u0038\u0032\u004c\u0069\u0033\u007e\u002d\u0042\u0043\u0031\u0053\u0067\u0045\u0028\u0054\u002d\u0035\u0060\u007e\u0051\u007c\u005d\u0029\u007b\u0076\u003a\u002b\u007e\u0055\u003c\u0048\u0052\u002e\u0050\u0071\u0044\u0044\u0038\u0040\u0055\u006f\u0022\u0051\u002c\u0052\u0059\u0078\u0061\u006d\u0026\u002b\u002d\u007d\u0073\u002d\u0055\u0047\u006e\u0079\u0060\u0034\u0049\u0044\u003a\u003b\u005a\u0030\u004f\u0024\u007c\u0037\u0053\u006c\u007b\u0049\u002c\u006a\u0027\u006b\u0054\u0063\u0059\u003d\u0051\u0052\u0048\u0039\u004b\u0025\u0067\u0076\u0056\u0068\u0022\u0048\u004b\u0040\u0024\u0050\u0065\u0046\u005b\u0030\u003b\u0049\u0048\u0041\u006d\u005d\u002d\u0055\u005b\u0028\u0038\u0023\u005f\u004a\u0077\u006d\u003c\u004e\u0072\u006e\u0044\u0076\u006f\u0036\u0066\u0061\u007d\u006b\u0035\u0053\u003f\u0052\u0078\u0077\u0062\u0066\u0055\u0053\u0077\u0036\u0030\u0044\u0071\u0038\u0045\u005a\u0074\u0038\u0053\u002d\u002c\u005e\u0067\u0058\u0022\u0045\u0070\u0065\u005d\u0043\u006a\u002c\u0060\u0039\u0051\u0044\u006b\u0079\u0035\u0057\u005b\u007b\u0026\u0077\u004e\u0048\u0072\u006a\u0065\u0075\u006d\u0031\u006a\u002c\u0042\u0047\u0027\u006b\u0020\u0049\u0048\u0067\u0023\u006e\u0072\u0025\u0040\u007a\u0037\u004a\u006b\u0032\u0058\u0035\u0078\u0038\u005c\u0040\u0053\u0039\u0050\u004a\u0039\u0037\u006c\u0031\u0043\u0050\u006a\u007a\u0022\u0068\u0063\u0078\u0034\u0074\u0039\u004a\u0028\u0072\u0074\u0065\u004d\u0023\u007c\u005b\u0034\u004b\u0024\u0028\u0055\u002e\u007e\u0037\u0034\u0035\u0060\u003b\u005d\u0039\u0044\u0077\u0066\u0066\u0038\u0049\u0024\u005d\u003b\u0037\u0066\u006d\u0062\u006d\u0048\u005e\u0021\u004e\u0039\u0042\u0055\u0021\u0037\u0038\u0038\u002f\u0039\u0044\u0030\u004d\u004f\u007e\u002a\u004a\u0021\u0021\u0039\u0044\u0076\u0032\u002b\u003d\u0068\u0020\u0028\u0021\u0044\u005a\u0064\u0074\u0067\u0048\u005e\u0036\u0047\u0068\u0025\u0066\u003e\u0076\u002d\u003c\u004c\u007c\u002b\u0029\u0037\u0074\u004e\u003b\u0027\u0063\u004b\u0048\u0033\u0078\u0025\u0076\u003b\u0034\u0061\u0047\u002f\u005a\u002f\u006e\u0053\u006a\u0039\u0028\u006b\u0045\u0051\u006d\u006d\u0023\u0033\u0070\u0021\u0026\u0032\u0020\u0072\u0034\u0023\u0062\u0040\u0039\u0077\u005d\u0069\u0075\u005f\u0051\u0064\u0062\u005d\u005f\u007c\u007c\u0033\u0039\u005d\u005b\u0063\u005f\u0032\u0065\u0022\u0040\u0044\u0030\u0078\u006e\u0044\u0047\u0072\u004c\u0064\u007a\u0077\u0037\u0060\u0030\u0076\u003d\u006e\u003f\u0058\u007d\u005d\u0072\u0070\u0048\u006c\u005c\u0061\u0058\u0058\u0022\u005e\u007c\u003d\u004d\u0068\u006c\u0028\u006b\u004e\u0059\u0079\u0061\u003a\u007c\u0062\u0053\u0033\u0024\u007a\u007e\u0065\u0044\u0035\u0039\u0077\u006b\u0070\u006f\u0030\u0070\u0028\u0060\u002a\u0027\u0078\u007a\u0047\u002b\u0078\u0031\u0054\u0055\u0029\u0064\u0064\u004b\u004a\u0042\u0065\u006b\u006c\u005a\u004f\u0059\u0036\u0043\u0063\u006e\u0054\u0070\u0079\u003e\u0052\u004f\u0046\u003c\u005d\u002a\u0028\u0049\u0021\u0051\u0064\u0048\u0025\u002c\u002e\u0033\u0026\u0031\u0057\u005a\u0041\u006d\u0071\u0072\u0071\u0027\u0055\u0048\u004f\u0024\u004a\u004a\u005b\u0022\u002e\u0050\u0022\u0072\u0078\u0023\u0053\u006c\u0040\u0064\u0042\u0027\u0039\u0020\u002b\u0074\u007e\u0059\u006a\u007d\u0029\u002e\u0048\u003f\u0052\u005e\u0061\u0056\u0020\u0020\u006e\u0047\u0068\u0035\u0050\u0067\u002b\u004f\u0047\u0025\u002a\u004e\u0074\u007b\u004e\u0060\u002e\u0065\u0042\u0043\u0073\u0068\u007b\u0044\u004d\u007e\u0066\u0067\u005f\u0052\u004a\u0053\u0070\u0033\u0079\u002a\u0062\u0074\u007c\u003f\u0077\u003f\u004d\u005f\u002d\u002d\u0041\u0067\u007c\u006a\u004d\u0036\u0062\u0037\u007e\u0051\u0029\u007b\u0025\u003c\u0045\u0049\u006a\u004e\u0040\u0055\u004e\u0033\u007b\u0067\u004d\u005f\u0057\u007c\u0064\u0052\u0072\u0040\u0040\u0031\u0061\u0067\u002f\u0029\u0051\u0071\u0025\u0022\u0049\u0078\u0055\u0049\u0054\u004d\u002c\u005a\u0022\u003a\u0055\u002c\u002a\u003e\u0056\u0024\u003d\u0042\u0065\u0046\u0022\u0053\u003d\u0045\u004f\u0039\u0071\u0070\u0051\u0039\u002b\u0070\u0060\u004e\u006d\u0065\u0033\u0037\u0040\u0051\u0048\u0059\u0076\u007b\u004d\u0037\u002a\u0040\u002a\u004b\u004d\u005e\u0033\u0057\u0046\u005e\u0032\u0069\u0052\u004f\u003d\u006d\u0064\u005a\u0074\u003e\u0033\u0070\u0079\u0046\u0027\u0042\u0077\u007d\u004d\u005a\u007c\u0067\u004f\u007b\u0037\u004e\u005f\u004b\u0039\u004e\u002d\u0040\u0038\u0035\u002e\u0076\u0062\u0073\u0039\u0046\u005a\u0049\u0020\u0068\u0025\u0053\u005c\u006c\u0037\u0051\u006e\u0042\u004c\u003e\u0029\u0029\u002c\u0053\u0041\u007b\u002b\u004d\u0033\u0047\u0069\u006a\u0033\u003b\u005a\u006d\u0063\u0057\u0073\u0045\u002a\u0023\u0067\u0068\u004d\u0042\u0058\u0076\u0062\u004b\u0058\u0044\u0027\u0047\u0020\u0024\u0020\u007c\u0038\u0066\u0071\u0062\u0040\u0071\u0027\u005f\u0021\u0031\u005f\u0020\u0046\u0027\u0062\u0029\u0024\u0047\u0039\u0032\u006a\u0063\u006c\u004a\u0057\u0054\u006a\u0027\u0025\u0071\u007a\u0065\u0067\u0038\u0051\u0052\u0065\u0078\u006b\u007c\u0074\u0052\u0068\u0037\u007a\u003f\u005d\u0052\u005e\u002f\u0076\u0026\u0037\u0047\u0039\u003e\u0063\u005c\u0051\u005b\u0073\u0029\u0057\u004e\u0021\u0065\u0064\u0037\u003d\u0032\u0068\u002c\u0062\u0035\u0071\u0028\u0066\u0025\u006e\u0077\u004f\u006b\u0063\u0041\u002d\u0046\u0052\u0053\u004e\u0049\u0039\u0052\u0058\u005d\u003e\u0056\u0040\u006d\u0071\u005e\u0057\u0045\u0058\u0040\u0066\u005f\u0030\u0059\u0036\u0070\u0048\u0074\u0043\u004f\u0035\u0071\u0020\u002f\u0055\u0057\u0065\u0020\u0025\u0032\u007d\u006d\u005e\u0022\u0026\u0071\u0059\u0063\u003b\u0079\u0035\u0062\u0054\u0060\u006c\u0038\u0030\u0048\u0050\u005c\u0042\u0041\u005d\u0079\u0026\u0024\u0054\u004c\u0021\u0034\u006d\u0041\u0038\u0021\u0032\u0052\u0063\u004d\u0059\u005a\u0037\u006e\u0076\u006b\u003e\u0073\u0029\u002e\u002b\u0040\u0040\u006a\u0078\u0041\u0055\u0078\u002a\u0053\u0061\u003f\u007e\u007a\u0022\u0047\u0020\u007d\u0054\u003c\u0030\u0026\u0043\u0029\u0023\u004f\u0043\u004f\u0063\u0029\u0020\u0025\u005a\u003c\u0062\u0035\u0050\u0027\u0041\u006a\u0077\u0033\u004e\u0026\u006b\u0061\u004c\u0052\u0053\u0048\u007b\u0020\u002b\u0032\u0059\u0053\u0036\u0035\u0024\u0074\u0055\u0027\u004d\u003f\u005f\u0024\u0038\u004c\u0057\u0078\u0047\u007a\u0039\u003c\u0062\u0055\u002f\u004d\u0050\u0034\u004f\u0070\u0055\u007a\u007a\u0078\u0076\u0056\u004d\u0070\u0024\u0050\u0048\u0030\u0066\u0066\u0069\u0051\u0059\u0063\u004d\u003f\u0043\u0039\u0047\u0026\u0037\u003e\u002d\u0038\u002d\u0051\u007c\u007b\u0027\u0056\u002c\u0061\u005f\u006d\u0051\u0067\u0040\u002d\u0021\u0041\u0051\u002d\u0079\u0040\u006b\u003c\u007e\u0077\u0057\u0053\u0045\u0075\u005f\u007b\u004f\u0038\u0044\u003c\u0031\u0077\u0057\u002b\u004b\u002b\u0079\u0027\u0076\u0068\u0069\u0033\u007c\u004b\u0073\u0075\u0076\u002b\u0073\u0041\u003a\u0051\u003b\u005c\u005a\u003e\u0060\u004c\u0074\u003c\u004e\u0076\u005e\u0047\u0077\u002b\u0025\u0065\u0071\u0048\u0078\u005a\u0046\u0062\u0056\u004e\u0044\u0064\u0048\u0033\u0031\u0069\u0031\u0028\u007a\u0043\u0044\u004c\u0047\u0046\u003c\u0071\u005c\u0056\u0039\u0030\u0052\u0072\u0055\u0064\u0054\u0028\u0022\u004e\u0031\u005d\u007c\u0067\u002c\u0049\u003a\u0071\u0034\u0027\u0070\u003b\u0056\u007e\u0058\u003f\u0058\u002c\u006b\u0047\u007c\u0024\u0061\u007b\u007e\u0046\u005d\u0072\u0031\u0036\u0051\u0030\u004e\u0023\u004f\u0074\u002e\u004f\u0078\u0026\u005c\u005e\u004c\u0029\u0025\u0056\u0055\u0040\u0026\u0074\u0054\u007b\u004a\u006b\u005e\u004c\u0079\u0069\u0047\u005a\u0051\u0075\u004a\u0042\u002e